import{C as r,o as l,c as o,a2 as e,E as i}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"从 0 到 100 开发计划","description":"Hearth 开发计划总览：按 7 个阶段模块推进，每个模块包含开发步骤、增量拆分、交付物和退出验收。","frontmatter":{"title":"从 0 到 100 开发计划","description":"Hearth 开发计划总览：按 7 个阶段模块推进，每个模块包含开发步骤、增量拆分、交付物和退出验收。","outline":[2,3]},"headers":[],"relativePath":"delivery/development-plan.md","filePath":"delivery/development-plan.md","lastUpdated":1793706118000}'),n={name:"delivery/development-plan.md"},c=Object.assign(n,{setup(s){const d=[{no:"S0",meta:"4 个增量",title:"定义与原型",text:"产品楔子、真实任务、原型、契约、评测与安全基线。",link:"/delivery/stage-0"},{no:"S1",meta:"6 个增量",title:"持久内核与 MVP",text:"走路骨架、Codex 切片、MVP-1、副作用安全与恢复。",link:"/delivery/stage-1"},{no:"S2",meta:"6 个增量",title:"Personal Operator",text:"只读连接器、文档与数据、网页研究、审批写入。",link:"/delivery/stage-2"},{no:"S3",meta:"4 个增量",title:"Computer Operator",text:"桌面 agentd、观察、接管、低风险与高风险 GUI。",link:"/delivery/stage-3"},{no:"S4",meta:"5 个增量",title:"主动个人 Agent",text:"Trigger、主动收件箱、手机 PWA、注意力预算。",link:"/delivery/stage-4"},{no:"S5",meta:"4 个增量",title:"记忆与进化",text:"Memory Core、遗忘、技能候选、评估、晋升与回滚。",link:"/delivery/stage-5"},{no:"S6",meta:"6 个增量",title:"多设备与长期运行",text:"同步、离线队列、撤销、备份迁移与长期运维。",link:"/delivery/stage-6"}];return(h,t)=>{const a=r("DocCardGrid");return l(),o("div",null,[t[0]||(t[0]=e('<p class="eyebrow">DEVELOPMENT PLAN</p><h1 id="从-0-到-100-开发计划" tabindex="-1">从 0 到 100 开发计划 <a class="header-anchor" href="#从-0-到-100-开发计划" aria-label="Permalink to &quot;从 0 到 100 开发计划&quot;">​</a></h1><p class="lead">产品路线图回答“做到哪里算完成”，开发计划回答“下一步具体做什么”。这里不是一条按周排期的甘特图，而是 7 个可独立验收的工程模块。</p><h2 id="本篇怎么读" tabindex="-1">本篇怎么读 <a class="header-anchor" href="#本篇怎么读" aria-label="Permalink to &quot;本篇怎么读&quot;">​</a></h2><ul><li>计划单位是纵向增量 <code>D0.1 … D6.6</code>，不是周、月或固定迭代长度。</li><li>严格按依赖顺序推进；任何增量都不能只交付后端、日志或接口。</li><li>每个增量都必须让用户在浏览器中完成一件具体的事。</li><li>阶段验收不通过时，停留在当前 Stage 修补，不用“后面再补”换取推进。</li></ul><h2 id="先看总纲" tabindex="-1">先看总纲 <a class="header-anchor" href="#先看总纲" aria-label="Permalink to &quot;先看总纲&quot;">​</a></h2><p><a href="/hearth-os/delivery/roadmap.html">分阶段产品路线图</a>是范围和顺序的总纲：它定义 Stage 0–6 的目标、范围、退出条件和明确推迟项。开发计划把同一套阶段展开为工程步骤；两者冲突时，以产品路线图的阶段门槛为准。</p><h2 id="七个开发模块" tabindex="-1">七个开发模块 <a class="header-anchor" href="#七个开发模块" aria-label="Permalink to &quot;七个开发模块&quot;">​</a></h2>',8)),i(a,{items:d,columns:2}),t[1]||(t[1]=e('<p>进入任一模块后，按同样的顺序阅读：</p><ol><li><strong>前置条件</strong>：确认依赖已经满足，不把未稳定的能力带入下一阶段。</li><li><strong>开发步骤</strong>：按编号施工，每一步都说明要做什么、产出什么。</li><li><strong>增量拆分</strong>：确认每个增量对应的用户可见结果和完成证据。</li><li><strong>退出验收</strong>：全部通过才进入下一模块；不通过就留在当前模块修补。</li></ol><h2 id="计划边界" tabindex="-1">计划边界 <a class="header-anchor" href="#计划边界" aria-label="Permalink to &quot;计划边界&quot;">​</a></h2><ul><li><strong>起点：</strong> 有产品定义、首位用户和空仓库，但没有可运行系统。</li><li><strong>终点：</strong> 通过全部阶段出口，能在真实个人环境中长期使用、迁移、恢复和撤销的 Personal Agent OS。</li><li><strong>单位：</strong> 纵向增量，例如 D0.1、D1.1、D2.3；不是周、月或固定迭代长度。</li><li><strong>顺序：</strong> 严格按依赖推进；可以暂停、试用和回退，但不能用跳过恢复、界面或验证来换取速度。</li></ul><h2 id="六条执行规则" tabindex="-1">六条执行规则 <a class="header-anchor" href="#六条执行规则" aria-label="Permalink to &quot;六条执行规则&quot;">​</a></h2><ol><li><strong>纵向切片优先。</strong> 每个增量都必须同时有用户结果、界面、持久状态、真实实现、验证和恢复。</li><li><strong>前端同步生长。</strong> Stage 0 有可点击原型；Stage 1 的第一个可运行骨架就有真实 Web 任务卡；之后每个增量都要投影到界面。</li><li><strong>先窄后宽。</strong> 先让一个任务族真正可依赖，再增加第二个任务族；先在一个连接器上证明权限、幂等和回执，再扩展渠道。</li><li><strong>持久性先于自主性。</strong> 任务不能丢、副作用不能重复、失败必须可见；在这些完成前，不增加主动循环和高风险无人值守。</li><li><strong>安全先于真实副作用。</strong> 发送、写入、分享、删除和桌面操作，必须先经过 Effect Preview、Mandate、Approval、幂等键和 Receipt 演练。</li><li><strong>评估先于扩展。</strong> 新增执行器、连接器、模型、技能或自动化范围前，必须有代表性任务、基线、失败样本和回滚路径。</li></ol><h2 id="mvp-的位置" tabindex="-1">MVP 的位置 <a class="header-anchor" href="#mvp-的位置" aria-label="Permalink to &quot;MVP 的位置&quot;">​</a></h2><p>MVP-1 位于 Stage 1 的早期出口，对应 D1.3，不是 Stage 6 的产物。它是一个真实可用的本地个人任务工作台，默认以“研究/文档整理”为第一个任务楔子；如果首位用户最高频的是代码任务，可以替换楔子，但纵向结构不变。</p><table tabindex="0"><thead><tr><th>维度</th><th>MVP 门槛</th></tr></thead><tbody><tr><td>入口</td><td>本地 Web 可创建任务、选择工作区、引用文件或路径</td></tr><tr><td>任务</td><td>一个窄任务族的完整闭环：目标、范围、预算、状态和验收</td></tr><tr><td>执行</td><td>Codex 在隔离工作区执行，返回结构化结果和产物</td></tr><tr><td>状态</td><td>排队、执行、审批、需要信息、完成、失败和可恢复状态真实持久化</td></tr><tr><td>界面</td><td>今日/任务卡、详情、审批、产物、失败与恢复，不要求 CLI 知识</td></tr><tr><td>证据</td><td>产物可预览/下载，带来源、哈希和验证结果</td></tr><tr><td>副作用</td><td>至少一种外部动作有预览、审批、幂等与练习回执</td></tr><tr><td>恢复</td><td>刷新或重启后任务不消失，能继续、取消、重试或转人工</td></tr><tr><td>成本</td><td>记录 Token、模型、执行器、延迟和人工分钟</td></tr></tbody></table><h2 id="每个增量的交付模板" tabindex="-1">每个增量的交付模板 <a class="header-anchor" href="#每个增量的交付模板" aria-label="Permalink to &quot;每个增量的交付模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>必须回答</th></tr></thead><tbody><tr><td>用户可见结果</td><td>用户在浏览器里能多做哪一件具体的事？</td></tr><tr><td>主要工作</td><td>哪些后端、前端、协议、执行器和测试工作需要完成？</td></tr><tr><td>完成门槛</td><td>用什么可重复的证据证明它真的完成？</td></tr><tr><td>失败与恢复</td><td>失败时用户看到什么，如何取消、重试、接管或撤销？</td></tr><tr><td>成本与副作用</td><td>Token、人工分钟、外部动作和回执是什么？</td></tr><tr><td>回归检查</td><td>上一个增量、上一阶段和关键安全边界是否仍然成立？</td></tr></tbody></table><h2 id="贯穿全部增量的五条工作线" tabindex="-1">贯穿全部增量的五条工作线 <a class="header-anchor" href="#贯穿全部增量的五条工作线" aria-label="Permalink to &quot;贯穿全部增量的五条工作线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工作线</th><th>每个增量必须更新</th></tr></thead><tbody><tr><td>产品与界面</td><td>用户故事、状态、主动作、空状态、失败态、恢复入口、桌面/手机布局</td></tr><tr><td>协议与投影</td><td>Event、schema、API、Task Pack、Result、投影字段、migration 和契约测试</td></tr><tr><td>评测与安全</td><td>代表性任务、成功/失败样本、权限检查、故障注入、安全回归和人工验收</td></tr><tr><td>可观测与成本</td><td>trace、执行器/模型、Token、延迟、人工分钟、打断次数、失败分类</td></tr><tr><td>文档与迁移</td><td>README、ADR、用户说明、安全、备份/升级、已知限制和数据导出</td></tr></tbody></table><h2 id="可演示节点" tabindex="-1">可演示节点 <a class="header-anchor" href="#可演示节点" aria-label="Permalink to &quot;可演示节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>对应模块</th><th>可演示的产品状态</th></tr></thead><tbody><tr><td>原型</td><td>S0</td><td>可点击的完整任务流程，不产生真实副作用</td></tr><tr><td>走路骨架</td><td>S1 · D1.1</td><td>Web + 持久任务 + fake executor</td></tr><tr><td>MVP-1</td><td>S1 · D1.3</td><td>一个窄任务族的真实端到端产品</td></tr><tr><td>Stage 1 完成</td><td>S1</td><td>可恢复内核、两任务族、副作用安全骨架</td></tr><tr><td>Personal Operator</td><td>S2</td><td>邮件/日历/文档/网页/数据日常任务</td></tr><tr><td>Computer Operator</td><td>S3</td><td>GUI 观察、接管、低/高风险桌面动作</td></tr><tr><td>主动个人 Agent</td><td>S4</td><td>主动循环、手机 PWA、注意力预算</td></tr><tr><td>记忆与进化</td><td>S5</td><td>可纠正记忆、可回滚技能</td></tr><tr><td>Personal Agent OS</td><td>S6</td><td>多设备、迁移、长期运行与完整审计</td></tr></tbody></table><h2 id="范围裁剪顺序" tabindex="-1">范围裁剪顺序 <a class="header-anchor" href="#范围裁剪顺序" aria-label="Permalink to &quot;范围裁剪顺序&quot;">​</a></h2><p>资源不足时先裁剪范围，不裁剪地基：减少连接器和渠道 → 减少主动性 → 减少原生形态 → 减少高级记忆 → 减少多设备 → 减少远程 Sandbox → 暂停技能晋升。</p><p><strong>永远不能裁掉：</strong> Web 界面和任务卡、Event Log 和持久状态、审批/幂等/outbox/Receipt、验证器和失败样本、权限与秘密保护、导出/备份/撤销、用户可见的失败原因和下一步。</p><h2 id="完成定义" tabindex="-1">完成定义 <a class="header-anchor" href="#完成定义" aria-label="Permalink to &quot;完成定义&quot;">​</a></h2><p>“100%”不是所有软件和场景零人工，而是全部阶段出口同时成立：任务覆盖可验证；桌面与手机都能查看、发起、审批、接管和取回产物；崩溃与设备切换不丢任务；高风险动作可审批、可撤销；记忆可解释、可纠正、可遗忘；技能可评估、可回滚；系统可安装、可迁移、可长期运行。</p><h2 id="阶段推进检查表" tabindex="-1">阶段推进检查表 <a class="header-anchor" href="#阶段推进检查表" aria-label="Permalink to &quot;阶段推进检查表&quot;">​</a></h2><ul><li>[ ] 当前阶段退出条件都有证据，而不是口头宣布。</li><li>[ ] 最后一个增量仍能在浏览器中完整演示。</li><li>[ ] 从空数据库安装、启动、创建任务和恢复的路径可用。</li><li>[ ] 没有未解决的高风险安全、重复副作用或秘密泄露问题。</li><li>[ ] 新增能力都有失败态、恢复入口和用户可见说明。</li><li>[ ] 评测集、真实任务结果、Token/人工分钟和失败分类已更新。</li><li>[ ] 数据导出、备份、回滚和已知限制已更新。</li><li>[ ] 下一阶段不依赖隐藏的人工操作或只在开发机可用的配置。</li></ul>',22))])}}});export{b as __pageData,c as default};
